#!/usr/bin/env bash
# In-repo copy for tests/spec_runner.rs (unit U0, 2026-10-14). Source: the review package,
# local/spec/tutorial/run-spec-demo.sh. Changes from the source are marked U0-EDIT. Run through
# `cargo test --test spec_runner`, or scripts/behaviour-lock.sh spec to compare two binaries.
# evnx spec demo runner (SP0-SP10). Non-interactive, safe: each scene runs in its own temp folder.
# Usage: EVNX=/path/to/evnx ./run-spec-demo.sh [SP5 ...]
# "KNOWN" lines mark behaviour logged as an issue in the review (23-spec.md); they show 0.10.0 as it is today.
# Nothing here touches the network. All values are synthetic.
set -u
EVNX="${EVNX:-evnx}"
DEMO_ROOT="${DEMO_ROOT:-$(mktemp -d)}"
export NO_COLOR=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_SYSTEM=/dev/null
unset EVNX_PASSWORD EVNX_OUTPUT_JSON EVNX_AUTO_FIX
pass=0; fail=0
run() { echo; echo "\$ ${*/#$EVNX/evnx}"; "$@" > "$DEMO_ROOT/.out" 2>"$DEMO_ROOT/.err" </dev/null; local rc=$?; cat "$DEMO_ROOT/.out"; [ -s "$DEMO_ROOT/.err" ] && { echo "[stderr]"; cat "$DEMO_ROOT/.err"; }; echo "[exit $rc]"; LAST=$rc; }
expect() { if [ "$LAST" -eq "$1" ]; then pass=$((pass+1)); echo "  ok: $2 (exit $1)"; else fail=$((fail+1)); echo "  MISMATCH: $2 expected exit $1, got $LAST"; fi; }
check() { if eval "$1"; then pass=$((pass+1)); echo "  ok: $2"; else fail=$((fail+1)); echo "  MISMATCH: $2"; fi; }
scene() { echo; echo "================ $1 ================"; D="$DEMO_ROOT/$1"; rm -rf "$D"; mkdir -p "$D"; cd "$D" || exit 1; git init -q .; }
# a small, honest project: every value fits the format spec init will infer
app() { printf 'DATABASE_URL=postgres://user:pw@db.internal/app\nPORT=8080\nDEBUG=true\nADMIN_EMAIL=ops@example.com\nSTRIPE_SECRET_KEY=Zk3pQ9vL2mXw8RtY5nBc7dHfGj4sUe6Ao1iK\nMAX_RETRIES=5\n' > .env; printf 'DATABASE_URL=\nPORT=\nDEBUG=\nADMIN_EMAIL=\nSTRIPE_SECRET_KEY=\nMAX_RETRIES=\n' > .env.example; }

# U0-EDIT (2026-10-14): SP0 D-127 flipped to exit 0, fixed in 0.10.1.
SP0() { scene SP0; run "$EVNX" spec --help; run "$EVNX" spec init --help; check '"$EVNX" spec init --help | grep -q "django,postgres,redis"' "the --help example names django,postgres,redis"; run "$EVNX" spec init --with django,postgres,redis --stdout; expect 0 "D-127 fixed in 0.10.1 (component aliases, 3cc6ed4; DEC-SP12): the --help example works"; run "$EVNX" spec init --with nonsense --stdout; expect 2 "unknown component: exit 2 with suggestion"; run "$EVNX" spec init --bogus; expect 2 "unknown flag: exit 2"; }
# R-SPEC-EDIT (2026-10-17): SP1 flipped — I-184 (DEC-SP10: a URL with a password is secret); entries keep the template order (DEC-SP9).
SP1() { scene SP1; app; run "$EVNX" spec init; expect 0 "first spec from .env.example + .env"; run cat .evnx.toml; check 'grep -q "^format = \"url\"" .evnx.toml && grep -q "^format = \"port\"" .evnx.toml && grep -q "^format = \"bool\"" .evnx.toml && grep -q "^format = \"email\"" .evnx.toml && grep -q "^format = \"int\"" .evnx.toml' "url, port, bool, email, int all inferred"; check '[ "$(grep -c "^secret = true" .evnx.toml)" = 2 ] && grep -A4 "^\[vars\.DATABASE_URL\]" .evnx.toml | grep -q "^secret = true"' "FIXED I-184 (DEC-SP10): STRIPE_SECRET_KEY by its name, DATABASE_URL because its URL carries a password"; run "$EVNX" validate; expect 0 "the project passes its own generated spec"; run "$EVNX" spec init; expect 2 "second run refuses (never a second [vars])"; check 'git diff --quiet 2>/dev/null || true; [ "$(grep -c "^\[vars\.DATABASE_URL\]" .evnx.toml)" = 1 ]' "file still has one DATABASE_URL table"; }
SP2() { scene SP2; run "$EVNX" spec init --with django,redis --stdout; check '"$EVNX" spec init --with django,redis --stdout 2>/dev/null | grep -q "# from Redis"' "each entry carries its own '# from <Component>'"; run "$EVNX" spec init --with django --verbose; expect 0 "writes .evnx.toml from the catalogue"; check 'grep -q "^description = " .evnx.toml' "descriptions come with the component"; run "$EVNX" spec init --with " django , django" --stdout; echo "KNOWN: spaces are trimmed and duplicates tolerated"; run "$EVNX" spec init --with Django --stdout; expect 2 "ids are case-sensitive: 'Django' is refused"; }
# U1-EDIT (2026-10-14): SP3 I-176 checks flipped on purpose: the banner moved to stderr (DEC-SP1, DEC-G1).
# U8-EDIT (2026-10-17): SP3 flipped — I-182 via DEC-SP3 (--force refused).
SP3() { scene SP3; app; run "$EVNX" spec init --stdout; expect 0 "--stdout writes no file"; check '[ ! -e .evnx.toml ]' "no .evnx.toml created"; "$EVNX" spec init --stdout > piped.toml 2>/dev/null; check '! grep -q "Generate the variable contract" piped.toml' "I-176 fixed (DEC-SP1, DEC-G1): the banner is on stderr, stdout is only TOML"; cp piped.toml .evnx.toml; run "$EVNX" validate; expect 0 "I-176 fixed: '> .evnx.toml' gives a config validate reads"; rm .evnx.toml; run "$EVNX" spec init --stdout --force; expect 2 "FIXED I-182 (U8d, DEC-SP3): --force is refused everywhere, with a hint to --merge"; }
# U8-EDIT (2026-10-17): SP4 flipped — I-178 (--merge, --force refused) and I-179 (nothing written that does not parse).
SP4() { scene SP4; app; printf '[scan]\nseverity = "high"\n\n[vars.A]\nrequired = false\n' > .evnx.toml; cp .evnx.toml before.toml; run "$EVNX" spec init; expect 2 "existing [vars]: refused"; check 'cmp -s .evnx.toml before.toml' "the file is untouched, byte for byte"; run "$EVNX" spec init --force; expect 2 "FIXED I-178 (U8d, DEC-SP3): --force is refused with a hint to --merge"; check 'cmp -s .evnx.toml before.toml' "still untouched"; run "$EVNX" spec init --merge; expect 0 "FIXED I-178: --merge adds only the names [vars] does not declare"; check '[ "$(grep -c "^\[vars\.A\]" .evnx.toml)" -eq 1 ] && head -c "$(wc -c < before.toml)" .evnx.toml | cmp -s - before.toml' "A kept as written, the hand-written start byte for byte"; check '"$EVNX" validate >/dev/null 2>&1; [ $? -ne 2 ]' "every command can read the merged config"; printf 'vars = { A = { required = false } }\n' > .evnx.toml; cp .evnx.toml before.toml; run "$EVNX" spec init; expect 2 "FIXED I-179 (U8d): an inline vars table is seen and refused"; run "$EVNX" spec init --merge; expect 2 "FIXED I-179: --merge cannot extend an inline table; nothing written"; check 'cmp -s .evnx.toml before.toml' "the file is untouched"; check '"$EVNX" validate >/dev/null 2>&1; [ $? -ne 2 ]' "and still readable"; }
SP5() { scene SP5; printf 'DB=\n' > .env.example; cat > .evnx.toml <<'T'
# my config
[vars.DB]
required = false
description = "mine"
T
cp .evnx.toml before.toml; run "$EVNX" add service redis --yes; check 'cmp -s <(head -4 .evnx.toml) before.toml' "hand-edited entry and comment are untouched"; check 'grep -q "^\[vars.REDIS_URL\]" .evnx.toml' "REDIS_URL appended to the contract"; check 'grep -A5 "^\[vars.REDIS_PASSWORD\]" .evnx.toml | grep -q "secret = true"' "REDIS_PASSWORD declared secret"; run "$EVNX" validate; echo "validate reads the appended entries"; cd "$DEMO_ROOT" && rm -rf SP5b && mkdir SP5b && cd SP5b && git init -q . && printf '[scan]\nseverity = "high"\n' > .evnx.toml; run "$EVNX" add service redis --yes; check '! grep -q "\[vars" .evnx.toml' "a config with no [vars] is never given one"; }
# R-SCAN-EDIT (2026-10-21): SP6 I-254 flipped — `[vars]` applies to app.env.
SP6() { scene SP6; printf 'LEGACY_TOKEN=abcdef0123456789abcdef0123456789\nAPP_NAME=demo\n' > app.env; printf '[vars.APP_NAME]\nsecret = true\n\n[vars.LEGACY_TOKEN]\nsecret = false\n' > .evnx.toml; run "$EVNX" scan app.env; echo "secret=true is the declaration; secret=false retracts only a name-based guess"; printf 'STRIPE_KEY=sk_live_%s\n' "$(printf 'a%.0s' {1..24})" > live.env; printf '[vars.STRIPE_KEY]\nsecret = false\n' > .evnx.toml; run "$EVNX" scan live.env; check '"$EVNX" scan live.env 2>&1 | grep -qi "stripe"' "a live key shape cannot be silenced by secret=false"; echo "FIXED I-254 (R-scan): declared secret=true applies to app.env"; }
# R-SPEC-EDIT (2026-10-17): SP7 flipped — I-187 (DEC-SP5: unknown [vars.X] keys warn everywhere, validate exits 1). I-188 stays KNOWN (0.11.0).
SP7() { scene SP7; printf 'A=\nB=x\n' > .env.example; printf 'A=\nB=x\n' > .env; printf '[vars.A]\nrequird = false\n\n[vars.B]\nsecrett = true\n' > .evnx.toml; run "$EVNX" validate; expect 1 "FIXED I-187 (DEC-SP5): 'requird' is an error naming the fix (did you mean \`required\`?); A stays required until it is spelt right"; check '"$EVNX" validate 2>&1 | grep -q "Unknown key \`requird\` in \[vars.A\]"' "FIXED I-187: validate reports the typo itself"; run "$EVNX" scan; check '"$EVNX" scan 2>&1 | grep -q "vars.B.secrett"' "FIXED I-187: every command names 'secrett' (did you mean \`secret\`?); B is not declared secret until it is spelt right"; printf 'B=x\n' > .env.example; printf '[vars.B]\nformat = "urll"\n' > .evnx.toml; printf 'B=x\n' > .env; run "$EVNX" validate; echo "KNOWN I-188: 'urll' became a regex and matched nothing sensible (decided DEC-SP6: unknown name is an error)"; }
# R-SPEC-EDIT (2026-10-17): SP8 flipped — I-180 (DEC-SP4: a format is written only when the sample fits it).
SP8() { scene SP8; printf 'PORT=0\nREDIS_PORT=70000\nDEBUG=2\nUSER_ID=18446744073709551616000\nOK=5\n' > .env; cp .env .env.example; run "$EVNX" spec init; expect 0 "spec init writes a contract from these values"; check '"$EVNX" spec init --stdout 2>&1 >/dev/null | grep -c "left out" | grep -qx 4' "FIXED I-180 (DEC-SP4): the four formats these values fail are left out and named on stderr"; run "$EVNX" validate; expect 0 "FIXED I-180 (DEC-SP4): the generated spec passes the project it came from"; }
# R-SPEC-EDIT (2026-10-17): SP9 flipped — I-177 (DEC-SP2: the root config is written), I-189 ([defaults] example and --env-name). The sub/ run gains --example: the root's [defaults] example now applies there.
SP9() { scene SP9; app; printf '[defaults]\nexample = "env.sample"\n' > .evnx.toml; printf 'SAMPLE_ONLY=\n' > env.sample; mkdir sub && cp .env .env.example sub/ && cd sub; run "$EVNX" spec init; expect 2 "FIXED I-189 (DEC-SP2): the root's [defaults] example = env.sample applies here too, as in validate, and sub/ has no env.sample"; run "$EVNX" spec init --example .env.example; expect 0 "run from sub/ with its own .env files; the config lives at the root"; check '[ ! -e .evnx.toml ] && grep -q "^\[vars\.DATABASE_URL\]" ../.evnx.toml && head -2 ../.evnx.toml | grep -q "^example = \"env.sample\""' "FIXED I-177 (DEC-SP2): written into the root config, kept as it was above; no second .evnx.toml in sub/"; cd ..; rm -rf sub; run "$EVNX" spec init --stdout; check '"$EVNX" spec init --stdout 2>/dev/null | grep -q "^\[vars\.SAMPLE_ONLY\]"' "FIXED I-189 (DEC-SP2): [defaults] example = env.sample is honoured"; run "$EVNX" spec init --env-name staging --stdout; expect 2 "FIXED I-189: --env-name exists; .env.staging is missing, so exit 2 naming the environments that exist"; printf 'STAGE_ONLY=1\n' > .env.staging; run "$EVNX" spec init --env-name staging --stdout; expect 0 "FIXED I-189: --env-name staging reads .env.staging"; check '"$EVNX" spec init --env-name staging --stdout 2>/dev/null | grep -A1 "^\[vars\.STAGE_ONLY\]" | grep -q "^# only in .env.staging"' "FIXED I-183: its own names follow the template's, marked '# only in .env.staging'"; }
# R-SPEC-EDIT (2026-10-17): SP10 flipped — I-182, I-186 (DEC-SP8), I-183 (DEC-SP9), I-184 (DEC-SP10); stale labels I-181 (fixed U1) and I-185 (fixed 0.10.1) now checked.
SP10() { scene SP10; app; "$EVNX" -q spec init --stdout > q.out 2> q.err; check '[ ! -s q.err ]' "stderr empty with -q"; rm -f .evnx.toml; run "$EVNX" -q spec init; check '[ -s .evnx.toml ]' "-q still writes the file"; check '! "$EVNX" -q spec init 2>&1 | grep -q "wrote"' "-q: a refusal prints no 'wrote'"; rm -f .evnx.toml; check '[ -z "$("$EVNX" -q spec init 2>&1)" ] && [ -s .evnx.toml ]' "FIXED I-181 (U1, DEC-SP8): -q prints nothing at all on success"; rm -f .evnx.toml; run "$EVNX" spec init --env nope.env --stdout; expect 2 "FIXED I-182 (DEC-SP8): an explicit --env that does not exist is an error"; run "$EVNX" spec init --with django --env .env --stdout; expect 2 "FIXED I-182 (DEC-SP8): --with reads no project file, so --env beside it is refused"; run "$EVNX" spec init --with ""; expect 2 "FIXED I-186 (DEC-SP8): nothing to write is exit 2"; printf 'DATABASE_URL=\n' > .env.example; printf 'DATABASE_URL=postgres://u:p@h/d\nONLY_IN_ENV=1\n' > .env; rm -f .evnx.toml; run "$EVNX" spec init --stdout; check '"$EVNX" spec init --stdout 2>/dev/null | grep -A2 "^\[vars\.ONLY_IN_ENV\]" | grep -q "^required = false"' "FIXED I-183 (DEC-SP9): a name only in .env is included after the template's, required = false, marked '# only in .env'"; check '"$EVNX" spec init --stdout 2>/dev/null | grep -A4 "vars.DATABASE_URL" | grep -q "^secret = true"' "FIXED I-184 (DEC-SP10): a URL with a password is secret = true"; check '"$EVNX" spec init --with django --stdout 2>/dev/null | head -1 > /dev/null; [ "${PIPESTATUS[0]}" -ne 101 ]' "FIXED I-185 (0.10.1): a reader that stops early ends evnx quietly, no panic"; }

if [ $# -eq 0 ]; then set -- SP0 SP1 SP2 SP3 SP4 SP5 SP6 SP7 SP8 SP9 SP10; fi
for s in "$@"; do "$s"; done
echo; echo "================ summary: $pass ok, $fail mismatch  (scratch: $DEMO_ROOT) ================"
[ "$fail" -eq 0 ]
